    """Coerce a numeric value to Decimal, accepting floats via their repr."""
    if isinstance(value, bool):
        raise BillingError(code, repr(value))
    if isinstance(value, float):
        value = Decimal(str(value))
    try:
        result = to_money(value)
    except BillingError:
        raise BillingError(code, repr(value)) from None
    if not result.is_finite():
        raise BillingError(code, repr(value))
    return result


def apply_discount(amount, percent):
    """``amount`` reduced by ``percent`` percent, rounded to the cent."""
    amount = _as_decimal(amount, "invalid_amount")
    percent = _as_decimal(percent, "invalid_percent")
    discounted = amount * (Decimal(100) - percent) / Decimal(100)
    return round_money(discounted)
